# -*- coding: utf-8 -*-
"""Batch 2 (G004–G013): activities adapted from Trang Phan's Teaching Gallery (trangphan.org).
Rules for each game were written from the short gallery descriptions and should be reviewed by the author."""

H = {
 "en": ["Learning Goals", "Success Criteria", "Minds On", "Action", "Consolidation", "Differentiation", "Assessment", "Materials"],
 "vi": ["Mục tiêu bài học", "Tiêu chí thành công", "Khởi động", "Hoạt động chính", "Củng cố", "Phân hóa", "Đánh giá", "Tài liệu kèm theo"],
}
VH = {"en": ["Context", "Adapting for Vietnamese classrooms", "Lessons learned"],
      "vi": ["Bối cảnh", "Điều chỉnh cho lớp học Việt Nam", "Bài học rút ra"]}
DIFF = {"en": ("New ELLs: ", "Advanced students: "), "vi": ("Học sinh mới học tiếng Anh: ", "Học sinh khá: ")}
ASS = {"en": ("For learning: ", "As learning: ", "Of learning: "), "vi": ("Đánh giá vì học tập: ", "Đánh giá là học tập: ", "Đánh giá kết quả học tập: ")}

def plan(lang, goals, sc, minds, action, cons, dnew, dadv, ass, mats):
    h = H[lang]; out = []
    for title, items in zip(h, [goals, sc, minds, action, cons,
                                 [DIFF[lang][0] + dnew, DIFF[lang][1] + dadv],
                                 [ASS[lang][i] + a for i, a in enumerate(ass)], mats]):
        out.append("## " + title)
        out += ["- " + x for x in items]
    return "\n".join(out)

def vn(lang, rows, adapt, lessons):
    h = VH[lang]
    return "\n".join(["## " + h[0]] + [" | ".join(r) for r in rows] + ["## " + h[1]] + ["- " + x for x in adapt] + ["## " + h[2]] + ["- " + x for x in lessons])

def steps(pairs):
    return "\n".join(f"{a} :: {b}" for a, b in pairs)

ROW_SIZE = {"en": ["Class size", "~20–25 students", "~35 (primary) to ~45 (secondary)"], "vi": ["Sĩ số", "~20–25 học sinh", "~35 (tiểu học) đến ~45 (THCS, THPT)"]}
ROW_TIME = {"en": ["Lesson length", "At least 300 min of instruction a day; schools set the timetable", "35 min (primary), 45 min (secondary)"], "vi": ["Thời lượng", "Tối thiểu 300 phút học/ngày; nhà trường tự xếp thời khóa biểu", "35 phút (tiểu học), 45 phút (THCS, THPT)"]}

G = []
def add(**k): G.append(k)

